style.css:
@-moz-document domain("imgbb.com"), domain("ibb.co") {
:root {
    color-scheme: dark;
  }

  /* ---------- Base ---------- */
  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  body {
    background-image: none !important;
  }

  /* Soften every default light border to a subtle dark line */
  * {
    border-color: #262c33 !important;
  }

  /* ImgBB draws its dropdown carets and tooltip arrows as CSS triangles: a 0×0
     box whose unused border sides are transparent. The blanket reset above makes
     those sides opaque, so every caret renders as a solid rectangle. Restore the
     transparent sides and tint only the edge that forms the triangle. */
  .arrow-down,
  .arrow-down-shadow,
  .arrow-up,
  .arrow-up-shadow,
  .arrow-left,
  .arrow-right {
    border-color: transparent !important;
  }

  .arrow-down,
  .arrow-down-shadow {
    border-top-color: #c4cdd6 !important;
  }

  .arrow-up,
  .arrow-up-shadow {
    border-bottom-color: #c4cdd6 !important;
  }

  .arrow-right {
    border-left-color: #c4cdd6 !important;
  }

  .arrow-left {
    border-right-color: #c4cdd6 !important;
  }

  /* Same triangle trick for the TipTip tooltip pointer. */
  #tiptip_arrow,
  #tiptip_arrow_inner {
    border-color: transparent !important;
  }

  #tiptip_holder.tip_top #tiptip_arrow_inner {
    border-top-color: rgba(0, 0, 0, 0.8) !important;
  }

  #tiptip_holder.tip_bottom #tiptip_arrow_inner {
    border-bottom-color: rgba(0, 0, 0, 0.8) !important;
  }

  #tiptip_holder.tip_right #tiptip_arrow_inner {
    border-right-color: rgba(0, 0, 0, 0.8) !important;
  }

  #tiptip_holder.tip_left #tiptip_arrow_inner {
    border-left-color: rgba(0, 0, 0, 0.8) !important;
  }

  /* Active nav item and the current sort tab are marked by a 3px ImgBB-blue
     underline, which the blanket reset above flattens into the page line colour
     — leaving no visible "you are here". Re-tint just those borders. */
  .top-bar ul .pop-btn.current,
  .top-bar ul .top-btn-el.current,
  .content-tabs li.current,
  .content-tabs li:hover {
    border-color: #5fb0e6 !important;
  }

  /* Sort/embed tab labels take the page ink on the live site (color: inherit) and
     the current tab is marked ONLY by the underline above. The global link colour
     painted all five ImgBB blue, so every tab read as the active one and hovering
     changed nothing. Keep them neutral and let the states do the talking. */
  .content-tabs li a,
  .content-tabs li a span {
    color: #c4cdd6 !important;
  }

  .content-tabs li.current a,
  .content-tabs li.current a span {
    color: #e6edf3 !important;
  }

  .content-tabs li:hover a,
  .content-tabs li:hover a span {
    color: #9bd4ff !important;
  }

  /* The per-tab counter is a solid #d90000 pill the site labels #fff. The generic
     span colour reaches inside it, so the count sat at 3.6:1 on its own red.
     Restate the class LAST — it ties with the tab-label rules above on
     specificity, so only source order keeps it. */
  .content-tabs li a span.tab-count-block {
    color: #ffffff !important;
  }

  /* A "visited" tab is a DIFFERENT state, not a second active one: the site draws
     it with NO underline (border-bottom-color: transparent) and an orange-red
     label (#d93600). Tinting it blue alongside .current invented a second
     "you are here" marker and erased the state entirely. */
  .content-tabs li.visited {
    border-bottom-color: transparent !important;
  }

  .content-tabs li.visited a {
    color: #ff7b72 !important;
  }

  .content-tabs li.current.visited {
    border-color: #ff7b72 !important;
  }

  /* ---------- Headings / text ---------- */
  h1, h2, h3, h4, h5, h6,
  .phone-text-align-center,
  .text-dark,
  strong, b {
    color: #e6edf3 !important;
  }

  p, span, li, dd, dt, label, small, td, th, figcaption {
    color: #c4cdd6 !important;
  }

  .text-muted,
  .sub-text,
  .light-text,
  .input-label-meta,
  .meta,
  time {
    color: #8b949e !important;
  }

  /* Every form validation message on the sign-in, create-account and contact
     pages is a <span class="input-warning red-warning"> the site paints #d74634 —
     the ONLY thing marking it as an error. The generic span colour above reaches
     it, so "Invalid email" rendered in ordinary body grey, indistinguishable from
     the label beside it. The spans are empty until validation runs, so no
     load-time scan and no screenshot of a pristine form can see them. */
  .red-warning,
  .input-warning.red-warning {
    color: #ff7b72 !important;
  }

  /* ---------- Links ---------- */
  a {
    color: #5fb0e6 !important;
  }

  a:hover {
    color: #9bd4ff !important;
  }

  /* Logo / nav links should stay neutral-bright, not link-blue */
  .top-bar a,
  .top-bar-logo a,
  .header a.btn {
    color: #c4cdd6 !important;
  }

  .top-bar a:hover {
    color: #e6edf3 !important;
  }

  /* "About", "EN" and "Upload" are <span class="top-btn-text"> inside li.pop-btn,
     not links: the site is the only thing that tints them (and their caret)
     #2a80b9 on hover AND while the menu is open. The neutral nav colour above
     beat both rules, so hovering a nav menu changed nothing at all and, once the
     pointer left an open menu, nothing said which one was open. Scoped to
     .pop-btn/.opened so the "Create account" chip (an <a class="btn blue">) keeps
     its white label. */
  .top-bar .pop-btn:hover .top-btn-text,
  .top-bar .opened .top-btn-text {
    color: #9bd4ff !important;
  }

  .top-bar .pop-btn:hover .arrow-down,
  .top-bar .opened .arrow-down {
    border-top-color: #9bd4ff !important;
  }

  /* ---------- Top bar / header ---------- */
  .top-bar,
  .header-top-bar {
    background-color: #0d1117 !important;
    border-bottom: 1px solid #262c33 !important;
  }

  /* The header paints its real surface through a ::before layer
     (default rgba(255,255,255,0.9) frosted band) — re-dark it or the
     nav reads against a light-grey strip on every page. */
  #top-bar::before,
  .top-bar::before,
  .header-top-bar::before {
    background-color: #0d1117 !important;
    background-image: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
  }

  .top-bar a,
  .top-bar-logo,
  .top-bar .text {
    color: #c4cdd6 !important;
  }

  /* Pop-out menus (account / language / share dropdowns) */
  .pop-box,
  .pop-box-inner,
  .pop-box-menu,
  .pop-box-menucols,
  .dropdown,
  .dropdown-menu {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
    box-shadow: 0 6px 24px rgba(0, 0, 0, 0.55) !important;
  }

  /* The phone build swaps the pop-outs for a full-height slide-in panel whose
     <ul> keeps a hard-coded white background, and drops a #eee bar on top of each
     bottom sheet. Both only exist once the hamburger is tapped at phone width, so
     no load-time scan on any viewport reaches them — the mobile nav shipped as
     light-grey labels on white. */
  #menu-fullscreen > ul {
    background-color: #1c2128 !important;
  }

  .pop-box-header {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Inside a pop-out, arrow-up/arrow-down are the menu's own pointer tip and take
     the menu's surface colour, not the caret's glyph colour set further up. */
  .pop-box .arrow-up {
    border-bottom-color: #1c2128 !important;
  }

  .pop-box .arrow-down {
    border-top-color: #1c2128 !important;
  }

  /* The menu's arrow tip is a CSS triangle too: colour ONLY the edge that faces
     the menu, or the opposite border paints a second triangle (a diamond). */
  .pop-box::before,
  .pop-box::after,
  .arrow-box::before,
  .arrow-box::after {
    border-color: transparent !important;
  }

  .arrow-box-top::before,
  .arrow-box-top::after {
    border-bottom-color: #1c2128 !important;
  }

  .arrow-box-bottom::before,
  .arrow-box-bottom::after {
    border-top-color: #1c2128 !important;
  }

  .pop-box a,
  .pop-box-menu a,
  .dropdown a {
    color: #c4cdd6 !important;
  }

  .pop-box a:hover,
  .pop-box-menu a:hover,
  .dropdown a:hover {
    background-color: #262c33 !important;
    color: #e6edf3 !important;
  }

  /* The currently-selected row (e.g. the active language in the language
     picker) keeps a near-white highlight pill — with our light menu text it
     becomes unreadable. Give it a subtle dark selected surface instead. */
  .pop-box .current a,
  .pop-box-menu .current a,
  .pop-box li.current > a {
    background-color: #2a7ab0 !important;
    color: #ffffff !important;
  }

  /* ---------- Main surfaces / panels ---------- */
  .content-width,
  .content-listing-container,
  .home-content,
  main,
  .page-content {
    background-color: transparent !important;
  }

  .panel,
  .panel-box,
  .box,
  .well,
  .image-viewer-sidebar,
  .sidebar,
  .modal,
  .modal-inner,
  .modal-box,
  .fullscreen-modal,
  .fullscreen-modal-box,
  #fullscreen-modal-box,
  .lightbox-content,
  .page-not-found,
  .empty-content,
  .content-box {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* Dismissing a modal after a field has been touched (the image "Edit" dialog)
     swaps its body for a confirm strip the site paints #fff — a full-width white
     band across the modal carrying our light body text at about 1.6:1. It only
     exists once a value has changed AND the dialog is closed, so no load-time
     scan and no screenshot of an untouched form reaches it. */
  #fullscreen-changes-confirm {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  /* Section headers ("Share", "Embed codes", related blocks) */
  .header,
  .header-content {
    background-color: transparent !important;
    color: #e6edf3 !important;
  }

  /* On listing and album pages the sort-tab header pins to the top of the
     viewport (position: sticky) and the site gives it a near-opaque surface.
     The transparent rule above matches it too, so thumbnails scrolled straight
     through the tabs and the labels sat on top of the photos. A sticky bar is
     in flow at offset 0 and looks perfect there — it only breaks once scrolled.
     Below the phablet breakpoint the tab <ul> itself carries that surface. */
  .header.follow-scroll,
  .follow-scroll-wrapper.position-fixed,
  .header ul.content-tabs {
    background-color: #14181d !important;
  }

  .header .header-content-title,
  .header h1,
  .header h2 {
    color: #e6edf3 !important;
  }

  /* ---------- Upload landing ---------- */
  .upload-box {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .upload-box-inner,
  .upload-box-heading,
  .upload-box-status {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* The 100px hero glyph is an icon FONT, so the generic span colour above
     repaints it grey. It is ImgBB blue on the live site — keep it branded. */
  .upload-box-heading .icon {
    color: #3a8fd6 !important;
  }

  /* ImgBB states its outcomes with .color-* utility classes on that same 100px
     glyph: the "Upload complete" tick is .color-green (#27ae61) and the failure
     mark is .color-red (#e74c3c). The hero rule above is a descendant selector, so
     it outranks the site's own utility and painted BOTH ImgBB blue — a failed
     upload rendered identically to a successful one. Restore the two outcomes. */
  .upload-box-heading .icon.color-green,
  .icon.color-green {
    color: #4ecb7d !important;
  }

  .upload-box-heading .icon.color-red,
  .icon.color-red {
    color: #ff7b72 !important;
  }

  .home-buttons,
  .home-content {
    background-color: transparent !important;
  }

  /* "About / Pro account" promo + pricing tiers on the landing page */
  .about,
  .inner-cover {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  .pricing-tier-box {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .pricing-tier-price,
  .pricing-tier-box .header,
  .pricing-tier-box h1,
  .pricing-tier-box h2,
  .pricing-tier-box h3 {
    color: #e6edf3 !important;
  }

  /* Despite the name, .background-red/-blue/-grey set NO background: each only
     overrides the 10px border-top on the plan heading, which is the whole
     colour code of the pricing table. Keep the heading on the card surface... */
  .pricing-tier-box .header,
  .pricing-tier-box .background-red,
  .pricing-tier-box .background-blue,
  .pricing-tier-box .background-grey {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  /* ...and re-tint that accent bar, which the blanket border reset above
     flattened to the page line colour — leaving all three plans identical. */
  .pricing-tier-box .background-red {
    border-top-color: #e74c3c !important;
  }

  .pricing-tier-box .background-blue {
    border-top-color: #2a80b9 !important;
  }

  .pricing-tier-box .background-green {
    border-top-color: #27ae60 !important;
  }

  .pricing-tier-box .background-orange {
    border-top-color: #f39c12 !important;
  }

  .pricing-tier-box .background-purple {
    border-top-color: #9b59b6 !important;
  }

  .pricing-tier-box .background-yellow {
    border-top-color: #f1c40f !important;
  }

  /* #bdc3c7 natively — dropped to a muted grey so the "no discount" tier does
     not read as a bright bar on the dark card. */
  .pricing-tier-box .background-grey {
    border-top-color: #8b949e !important;
  }

  .pricing-tier-box .background-midnight {
    border-top-color: #44586c !important;
  }

  /* The discount corner banner: the .pricing-ribbon container is just an
     overflow-hidden clip window — only its inner rotated div is the actual
     red flag, so colour ONLY that div (colouring the container fills the
     whole corner with a red block). Tuned darker for readable white text. */
  .pricing-ribbon > div {
    background-color: #a3261b !important;
    color: #ffffff !important;
  }

  /* The big drag-and-drop hero / drop overlay */
  .anywhere-upload-input-overlay,
  .anywhere-upload-input,
  .drop-zone,
  .dragging-overlay {
    background-color: rgba(13, 17, 23, 0.92) !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Upload-queue thumbnail tiles (shown right after picking a file, before the
     final "Upload" press). Each tile defaults to a flat #efefef square that
     glares white while the preview renders / for letterboxed images. Darken
     the tile; the preview <canvas>/<img> paints on top and is untouched. */
  .queue-item,
  .queue-output {
    background-color: #0d1117 !important;
  }

  /* The floating edit / cancel control chips on each tile are solid white
     circles — re-surface them dark with a light glyph so they don't punch two
     bright dots over every thumbnail. */
  .queue-item-button,
  .queue-item-button.edit,
  .queue-item-button.cancel {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* Upload progress track inside a tile is a translucent-white bar; darken the
     empty track. The coloured fill segment keeps its own inline width. */
  .queue-item .progress-bar {
    background-color: #2d333b !important;
  }

  /* When a tile finishes, an absolutely-positioned .result overlay covers it: a
     white check on success, and on failure a rgba(255,255,255,.65) veil behind a
     red warning triangle. The generic `span` colour repaints BOTH glyphs the same
     grey, so a failed upload became indistinguishable from a successful one — and
     the veil punched a white square over the thumbnail. These states only exist
     after an upload settles, so no load-time scan can reach them. */
  .upload-box-queue .failed .result {
    background-color: rgba(13, 17, 23, 0.72) !important;
  }

  .upload-box-queue .result .icon {
    color: #e6edf3 !important;
  }

  .upload-box-queue .failed .result .icon {
    color: #ff7b72 !important;
  }

  /* ---------- Image viewer stage ---------- */
  .image-viewer,
  .image-viewer-main,
  .image-viewer-container,
  .full-viewer,
  .viewer-image,
  .image-viewer-content {
    background-color: #0d1117 !important;
  }

  .image-viewer-main img,
  .viewer-image img {
    background-color: transparent !important;
  }

  /* Album filmstrip under the photo (prev/next thumbnails). It defaults to a
     near-white frosted bar (rgba(255,255,255,0.9)) that reads as a bright
     strip splitting the dark stage from the embed panel. Re-dark the bar and
     its scroll arrows; the thumbnail <img>s keep their own pixels. */
  .panel-thumbs,
  .panel-thumbs.follow-scroll {
    background-color: #0d1117 !important;
    border-color: #262c33 !important;
  }

  .panel-thumbs .arrow,
  .panel-thumbs-prev,
  .panel-thumbs-next,
  .panel-thumbs [class*="arrow"] {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  /* Inside the strip, every thumbnail slot is a #fff tile and the images sit at
     opacity .25 — the site fades the non-current thumbs INTO their tile (its own
     dark tone uses #000 here). Left white, each unselected thumb washed out to a
     milky-white square, and the tile is what the eye reads, not the photo. Fade
     them into the strip instead. */
  #panel-thumb-list li,
  .panel-thumb-list li {
    background-color: #0d1117 !important;
    /* Each slot also carries a 3px transparent bottom border for spacing, which the
       blanket reset at the top turned into an opaque line under every thumbnail. */
    border-bottom-color: transparent !important;
  }

  /* Guest / default user avatar is a flat #cccccc square (with a face-meh
     glyph) that glares as a bright box beside every uploader name on image
     and album pages. Give it an elevated dark surface; the icon stays a
     muted light so it still reads as an avatar placeholder. Real users' photo
     avatars paint via background-image and are unaffected. */
  .user-image.default-user-image,
  .default-user-image {
    background-color: #2d333b !important;
    color: #8b949e !important;
  }

  /* ---------- Image listing / thumbnail grid (albums, related) ---------- */
  .list-item,
  .pad-image-listing,
  .image-container,
  .image-container-main {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* The caption is an absolutely-positioned overlay the site keeps TRANSPARENT,
     leaning on a text-shadow to stay legible over the photo. Given the tile
     surface colour it became an opaque band that cropped the bottom of every
     thumbnail — and over a photo the label has to stay white, not the link-blue
     the generic `a` colour left it. */
  .list-item-desc {
    background-color: transparent !important;
  }

  .list-item-desc,
  .list-item-desc a,
  .list-item-desc-title-link {
    color: #ffffff !important;
  }

  .list-item-image,
  .image-container .image,
  .img-poster {
    background-color: #0d1117 !important;
  }

  .list-item-desc-fade {
    background-image: linear-gradient(to bottom, rgba(28, 33, 40, 0), #1c2128) !important;
  }

  /* Clicking a thumbnail opens a full-screen lightbox whose root element carries
     BOTH .viewer and .list-item, so the tile-surface rule above paints its
     backdrop the card grey instead of the site's #000 photo field — the photo
     then floats on a grey-blue page. The node is built by JS on click, so no
     load-time scan reaches it, and the shift is black -> grey: achromatic on
     both sides, which the chroma diff cannot see either. Must come AFTER the
     .list-item group — the two selectors tie on specificity. */
  .viewer {
    background-color: #0d1117 !important;
  }

  /* Pagination only renders once a listing has a second page, so a short album
     never reaches it and no load-time scan sees the state: the site paints the
     hovered page number #f6f6f6, and the link-hover blue above then sits on a
     near-white pill at roughly 1.5:1. Its own dark tone uses a flat surface. */
  .content-listing-pagination a:hover {
    background-color: #21262d !important;
    color: #9bd4ff !important;
  }

  /* The page you are already on is not a target — the site explicitly strips its
     hover surface, and the rule above would hand one back. */
  .content-listing-pagination .pagination-current a:hover {
    background-color: transparent !important;
  }

  /* ---------- Static content pages (API docs, plugin, terms) ---------- */
  /* The API page frames its examples in light cards: .code is a 2px #ecf0f1 mat
     around the response textarea, which reads as a white border on the dark
     page, and inline <code> in a paragraph is a #f9f9f9 pill that swallows its
     own label once the generic body colour repaints the text light. */
  .code {
    background-color: #2d333b !important;
  }

  .text-content code {
    background-color: #0d1117 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  /* ---------- Password-protected content gate ---------- */
  /* Choosing "Private (password protected)" for an album or image serves a page
     type of its own (body#password-gate) whose whole card is a #f9f9f9 panel.
     Nothing on the public site links to it, so no crawl reaches it: the heading
     sat at about 1.5:1 as light grey on near-white. */
  .content-password-gate,
  .access-box-content {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .content-password-gate h1,
  .content-password-gate h1 .icon {
    color: #e6edf3 !important;
  }

  /* ---------- Tabbed share / embed-code panel ---------- */
  .tabbed-content,
  .panel-share,
  .panel-share-item,
  .tabs-content,
  .tabs-menu {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .tabs-menu a,
  .tabbed-content-nav a {
    color: #8b949e !important;
    border-color: #2d333b !important;
  }

  .tabs-menu a.active,
  .tabs-menu li.active a,
  .tabbed-content-nav a.active {
    color: #e6edf3 !important;
    border-bottom-color: #5fb0e6 !important;
  }

  .panel-share-input-label {
    color: #8b949e !important;
  }

  /* Below the phablet breakpoint the tabbed embed-code nav collapses into a
     single .tab-menu selector button, which the site paints a flat #eee pill.
     Our light label ("Embed codes") then sat on that light pill and was
     illegible. Only rendered on phone/phablet, so no desktop scan reaches it. */
  .tab-menu {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* ---------- Forms / inputs (link + embed-code fields) ---------- */
  input,
  textarea,
  select,
  .text-input,
  .input-text,
  .form-input input {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
  }

  input::placeholder,
  textarea::placeholder,
  .text-input::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  /* Password-strength meter track sits inside the password field as a light
     grey pill; darken the empty track so it doesn't read as a white bar. The
     coloured fill segment keeps its own inline width/colour. */
  .input-password-strength {
    background-color: #2d333b !important;
  }

  input:focus,
  textarea:focus,
  select:focus {
    border-color: #5fb0e6 !important;
  }

  /* Input "copy" addon group around the share/embed fields */
  .input-with-buttons,
  .input-buttons,
  .copy-hover-display {
    background-color: transparent !important;
  }

  /* "OR" divider on the sign-in page: the label is a span painted the page
     background to "cut" the rule line behind it — it stays white on dark and
     reads as a bright pill. Re-paint it to the base and mute the text. */
  .or-separator span {
    background-color: #14181d !important;
    color: #8b949e !important;
  }

  /* ---------- Buttons ---------- */
  .btn,
  button,
  input[type="button"],
  input[type="submit"] {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  .btn:hover,
  button:hover {
    background-color: #2d333b !important;
    color: #ffffff !important;
  }

  /* ImgBB marks its calls to action with semantic colour classes (.blue =
     primary, .green = upload/share, .red = discount/destructive). The flat .btn
     surface above collapses them all into the same grey, so "Upload", "Sign in"
     and "Create account" stop reading as actions. Re-tint each class, darkened
     just enough that the white label clears 4.5:1. */
  .btn.blue {
    background-color: #2a7ab0 !important;
    border-color: #2a7ab0 !important;
    color: #ffffff !important;
  }

  .btn.blue:hover {
    background-color: #24699a !important;
    color: #ffffff !important;
  }

  .btn.green {
    background-color: #1e8449 !important;
    border-color: #1e8449 !important;
    color: #ffffff !important;
  }

  .btn.green:hover {
    background-color: #1a7440 !important;
    color: #ffffff !important;
  }

  .btn.red {
    background-color: #b93226 !important;
    border-color: #b93226 !important;
    color: #ffffff !important;
  }

  .btn.red:hover {
    background-color: #a52c21 !important;
    color: #ffffff !important;
  }

  .btn.orange {
    background-color: #b8530b !important;
    border-color: #b8530b !important;
    color: #ffffff !important;
  }

  .btn.orange:hover {
    background-color: #a4490a !important;
    color: #ffffff !important;
  }

  /* Header CTA is an <a class="btn blue">, and the nav link colour above would
     otherwise win over the button colour and leave grey text on blue. */
  .top-bar a.btn.blue,
  .top-bar a.btn.green,
  .header a.btn.blue,
  .header a.btn.green {
    color: #ffffff !important;
  }

  /* Outline / plain variants are transparent chips with a coloured label (the
     viewer's "Like" button). Restore that after the filled colours above. */
  .btn.outline,
  .btn.plain {
    background-color: transparent !important;
  }

  .btn.plain {
    border-color: transparent !important;
  }

  .btn.blue.outline {
    color: #5fb0e6 !important;
    border-color: #2a7ab0 !important;
  }

  .btn.green.outline {
    color: #4ecb7d !important;
    border-color: #1e8449 !important;
  }

  .btn.red.outline {
    color: #ff7b72 !important;
    border-color: #b93226 !important;
  }

  .btn.grey.outline,
  .btn.white.outline {
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* Keep outline chips see-through on hover — the filled :hover colours above
     are more specific and would otherwise paint the chip its own accent, which
     leaves the accent-coloured label sitting on itself. */
  .btn.outline:hover,
  .btn.plain:hover {
    background-color: transparent !important;
  }

  .btn.blue.outline:hover {
    color: #9bd4ff !important;
    border-color: #5fb0e6 !important;
  }

  .btn.green.outline:hover {
    color: #6ee29a !important;
    border-color: #4ecb7d !important;
  }

  .btn.red.outline:hover {
    color: #ff9d96 !important;
    border-color: #ff7b72 !important;
  }

  /* A disabled control says so almost entirely through its label: the site mutes
     it to #999 on a flat #f6f6f6. The .btn colours above hand it the same bright
     label and surface as a live button, so the "Uploading" button mid-upload read
     as still clickable. Declared after the filled/outline :hover rules so it wins
     the tie against them. */
  .btn.disabled,
  .btn.disabled:hover {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    color: #6e7681 !important;
  }

  .btn.disabled.outline,
  .btn.disabled.outline:hover {
    background-color: transparent !important;
    border-color: #2d333b !important;
    color: #6e7681 !important;
  }

  /* Like / share action pills keep semantic accents */
  .btn-like,
  .liked {
    color: #ff7b72 !important;
  }

  /* Every ImgBB control labels itself with <span class="btn-icon"> and
     <span class="btn-text"> children, so the generic `span` colour up top
     repainted them grey and none of the .btn colours above ever reached a label:
     the white glyph on a green "Share", the blue label on an outline "Like" chip
     and the white wordmark on a brand sign-in chip all collapsed to one grey.
     Let each label take its own control's colour. */
  .btn-icon,
  .btn-text,
  .sign-text {
    color: inherit !important;
  }

  /* Social sign-in chips keep their brand fill and want a white label; the
     generic `a` colour would otherwise leak link-blue onto them. */
  .sign-service,
  .link-service {
    color: #ffffff !important;
  }

  /* The share sheet's brand chips are the same shape but a different class, and
     they were missed: the site paints their glyph #fff over the brand fill, our
     `a` colour beat that rule, and `.btn-icon { color: inherit }` then carried
     link-blue into every glyph — on the light-blue Twitter chip the bird all
     but disappeared. Only exists once "Share" is clicked. */
  .btn-social,
  .btn-social .btn-icon {
    color: #ffffff !important;
  }

  /* Mail is the one chip the site puts on a light grey fill, with a dark glyph. */
  .btn-social.btn-mail,
  .btn-social.btn-mail .btn-icon {
    color: #333333 !important;
  }

  /* Viewer action links: Edit is link-blue, Delete is destructive red, Approve is
     green. All three were flattened to the same grey, so "Delete" read exactly
     like "Edit" right next to it. */
  a.link span,
  a.link .icon {
    color: inherit !important;
  }

  a.link--delete,
  [data-action="delete"] {
    color: #ff7b72 !important;
  }

  a.link--approve {
    color: #4ecb7d !important;
  }

  /* ---------- Tables ---------- */
  table, tr, td, th {
    background-color: transparent !important;
    border-color: #262c33 !important;
  }

  thead th,
  .table-header {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  tbody tr:hover {
    background-color: #1c2128 !important;
  }

  /* ---------- Footer ---------- */
  .footer,
  footer {
    background-color: #0d1117 !important;
    border-top: 1px solid #262c33 !important;
    color: #8b949e !important;
  }

  /* Footer links are ImgBB blue on the live site. Muting them to the footer's own
     grey left "Terms of Service" and "Privacy Policy" darker than the sentence
     around them, with no cue at all that they are links. Keep them tinted. */
  .footer a {
    color: #5fb0e6 !important;
  }

  .footer a:hover {
    color: #9bd4ff !important;
  }

  /* ---------- Misc ---------- */
  hr {
    border-color: #262c33 !important;
  }

  ::selection {
    background-color: #2a7ab0 !important;
    color: #ffffff !important;
  }

  .phone-hr,
  .divider {
    background-color: #262c33 !important;
  }

  /* Notification / flash bars stay readable */
  .alert,
  .notification {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* ImgBB's two notice surfaces — the inline privacy panel (.highlight, #f9e79f)
     and the toast (.growl, #fff5b3) — are pale-yellow fields the site pairs with
     its own dark body text. The generic paragraph/span colour repainted that
     text our light grey and left it on the yellow, at roughly 1.6:1. Re-surface
     both in a dark amber so they still read as a notice rather than a panel. */
  .highlight,
  .growl {
    background-color: #33291a !important;
    color: #e6edf3 !important;
  }

  .highlight *,
  .growl * {
    color: #e6edf3 !important;
  }

  /* The toast's whole left edge is its severity accent; the blanket border reset
     at the top flattened it to the page line colour. */
  .growl {
    border-left-color: #f39c12 !important;
  }
}
